{
  "ContainsFormulation": true,
  "variablesInModel": [
    {
      "Number": 1,
      "Abbreviation": "x_{i, r}",
      "Name": "Route selection variable",
      "Description": "1 if train i follows route r; 0 otherwise",
      "Domain": "binary"
    },
    {
      "Number": 2,
      "Abbreviation": "v_{i, p, v}",
      "Name": "Speed profile selection variable",
      "Description": "1 if train i uses speed profile v on section p; 0 otherwise",
      "Domain": "binary"
    },
    {
      "Number": 3,
      "Abbreviation": "z_{i, j, p}",
      "Name": "Precedence variable",
      "Description": "1 if train i precedes train j at section p; 0 otherwise",
      "Domain": "binary"
    },
    {
      "Number": 4,
      "Abbreviation": "s_{i, p}",
      "Name": "Arrival/service time",
      "Description": "Arrival/service time of train i at section p",
      "Domain": "continuous"
    },
    {
      "Number": 5,
      "Abbreviation": "d_{i}",
      "Name": "Total delay",
      "Description": "Total delay experienced by train i",
      "Domain": "continuous"
    }
  ],
  "objective_functions": [
    {
      "Name": "Total delay minimization",
      "Number": 0,
      "equation": "\\min \\sum_{i \\in \\mathcal{I}} d_{i}",
      "description": "Minimize the total delay across all trains in the network",
      "VariablesIncluded": [
        5
      ],
      "Linear": true
    }
  ],
  "constraints": [
    {
      "Name": "Route selection constraint",
      "Number": 1,
      "equation": "\\sum_{r \\in \\mathcal{R}_i} x_{i, r} = 1, \\quad \\forall i \\in \\mathcal{I}",
      "description": "Each train must select exactly one route",
      "VariablesIncluded": [
        1
      ],
      "Linear": true
    },
    {
      "Name": "Speed profile selection constraint",
      "Number": 2,
      "equation": "\\sum_{v \\in \\mathcal{V}} v_{i, p, v} = 1, \\quad \\forall i \\in \\mathcal{I}, \\forall p \\in \\mathcal{P}",
      "description": "Each train must select exactly one speed profile for every section in its chosen route",
      "VariablesIncluded": [
        2
      ],
      "Linear": true
    },
    {
      "Name": "Timing and Speed-Dependent Travel",
      "Number": 3,
      "equation": "s_{i, \\text{path}(i, r, k+1)} \\geq s_{i, \\text{path}(i, r, k)} + \\sum_{v \\in \\mathcal{V}} (T_{i, \\text{path}(i, r, k), v} \\cdot v_{i, \\text{path}(i, r, k), v}) - M(1 - x_{i, r}), \\quad \\forall i, r, k",
      "description": "The arrival time at a subsequent section must account for the travel time of the current section",
      "VariablesIncluded": [
        1,
        2,
        4
      ],
      "Linear": true
    },
    {
      "Name": "DTG Separation",
      "Number": 4,
      "equation": "s_{j, p} \\geq s_{i, p} + \\sum_{v \\in \\mathcal{V}} (G_{i, v} \\cdot v_{i, p, v}) - M(1 - z_{i, j, p}), \\quad \\forall i, j \\in \\mathcal{I}, i \\neq j, \\forall p \\in \\mathcal{P}",
      "description": "Trains occupying the same section must be separated by a time gap depending on the leader's speed profile",
      "VariablesIncluded": [
        2,
        3,
        4
      ],
      "Linear": true
    },
    {
      "Name": "Reordering constraint",
      "Number": 5,
      "equation": "z_{i, j, p} + z_{j, i, p} = 1, \\quad \\forall i, j \\in \\mathcal{I}, i < j, \\forall p \\in \\mathcal{P}",
      "description": "Ensures only one train can be the leader at a section",
      "VariablesIncluded": [
        3
      ],
      "Linear": true
    },
    {
      "Name": "Delay Calculation",
      "Number": 6,
      "equation": "d_{i} \\geq s_{i, \\text{dest}} - S_{i, \\text{dest}}, \\quad \\forall i \\in \\mathcal{I}",
      "description": "The delay for a train is the difference between its actual arrival at the final section and its scheduled arrival time",
      "VariablesIncluded": [
        4,
        5
      ],
      "Linear": true
    }
  ]
}
